 if not t then return 0 end
 local h=0
 for i=1,256 do local v=t[i]
  if type(v)~='number' or v~=v or v==math.huge or v==-math.huge then return nil end
  h=(h*31+(v>=0 and v+2 or 1))%2147483647
 end
 return h
end
local function rect(fn,mid)
 local a,b,c,d=fn(mid)
 for _,v in ipairs({a,b,c,d})do if type(v)~='number' or v~=v or v<0 or v>1 then return false end end
 return type(a)=='number' and type(b)=='number' and type(c)=='number' and type(d)=='number' and a<c and b<d
end
local function guard(input,atlas)
 if input.mapId~=native.mapId or input.pair~=native.pair or input.isBorder
  or input.width~=48 or input.height~=40 or type(atlas.texels)~='function'
  or type(atlas.hasOver)~='function' or type(atlas.underRect)~='function'
  or type(atlas.overRect)~='function' then return false end
 for yi,row in ipairs(native.cells)do for xi,s in ipairs(row)do
  local c=input.cellAt(native.x0+xi-1,native.y0+yi-1)
  if not c or c.mid~=s[1]or c.collision~=s[2]or c.elevation~=s[3]
   or c.behavior~=(s[4]~=-1 and s[4]or nil)or c.layerType~=s[5]
   or c.walkable~=(s[6]==1)or c.category~=s[8]then return false end
 end end
 for mid,h in pairs(native.art)do
  if atlas.hasOver(mid)~=native.hasOver[mid] or not rect(atlas.underRect,mid)
   or (native.hasOver[mid] and not rect(atlas.overRect,mid))then return false end
  if hash(atlas.texels(mid,'under'))~=h[1]or hash(atlas.texels(mid,'over'))~=h[2]then return false end
 end
 return true
end
function P.ownership(input,comp,atlas)
 if comp.minX~=12 or comp.maxX~=22 or comp.minY~=0 or comp.maxY~=6
  or not guard(input,atlas)then return nil end
 return {{12,0,22,5,2,exclude={{16,4,18,5}}},{16,4,18,6,3},preserveGround={{17,6}},decorativeRest={{15,6,5},{19,6,5},{20,6,5},{21,6,5},{22,6,5}}}
end
function P.match(input,comp,atlas)
 if not guard(input,atlas)then return nil end
 if comp.minX==12 and comp.maxX==22 and comp.minY==0 and comp.maxY==5 then
  return {name='pewter-museum-main',nativeMuseumFreshRoof=freshRoof,museumSideParts=sides.main,wallRows=2,flatRoof=false,topArtVerified=true,hipEndMaterial={mid=649,x=13,y=1,layer='under'}}
 elseif comp.minX==23 and comp.maxX==27 and comp.minY==2 and comp.maxY==4 then
  return {name='pewter-museum-annex',nativeEmeraldAnnex=emeraldAnnex,nativeRowHeight=true,wallRows=1,flatRoof=false,topArtVerified=true}
 elseif comp.minX==16 and comp.maxX==18 and comp.minY==4 and comp.maxY==6 then
  return {name='pewter-museum-entry',wallRows=3,fullFacade=true,topArtVerified=false,capMaterial={mid=649,x=13,y=1,layer='under',tileWorld=1}}
 end
end
P.status='Pewter two-level roof and native siding reconstruction; concealed faces reconstructed; desktop review only'

return P
